      "具体信息：诺基亚回应退出中国大陆市场。据报道，诺基亚将大幅收缩在华业务，其在中国大陆的移动网络和网络基础设施业务将分批裁员，并分阶段关闭多个办公地点和工厂，预计大部分裁员将在今年年底前完成，未来或仅保留售后服务，“基本上意味着逐步退出这一市场”。对此，诺基亚未直接确认或否认，仅称因在华业务持续下滑，正调整在中国的运营布局。",
